'use strict';
const menu = document.querySelector('.menu-toggle');
menu?.addEventListener('click', () => {const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');document.querySelector('.header nav').classList.toggle('open',open);});
document.querySelectorAll('.header nav a').forEach(a=>a.addEventListener('click',()=>{menu?.setAttribute('aria-expanded','false');document.querySelector('.header nav').classList.remove('open');}));
const shots=[
{id:'01',title:'The coastal reveal',duration:12.4,resolution:'4K',motion:'Slow drone',size:'Wide',paid:true,position:'50% 50%',description:'A wide aerial coastline in warm golden-hour light. No people in frame.',tags:['coast','coastline','ocean','sea','golden','hour','sunset','drone','slow','wide','aerial','cliffs','no people'],source:'Atlantic_coast_014.mov',in:'00:00:08:12',out:'00:00:20:22',confidence:'0.94'},
{id:'02',title:'Cliffs in golden light',duration:9.2,resolution:'4K',motion:'Slow pan',size:'Wide',paid:true,position:'80% 60%',description:'Golden light moves across rugged cliffs above a teal Atlantic ocean.',tags:['coast','coastline','ocean','golden','hour','sunset','slow','wide','cliffs','no people'],source:'Atlantic_coast_021.mov',in:'00:00:31:05',out:'00:00:40:10',confidence:'0.91'},
{id:'03',title:'Beyond the headland',duration:18.0,resolution:'4K',motion:'Slow drone',size:'Wide',paid:false,position:'35% 28%',description:'A long establishing shot along the headland. This sample record is restricted to editorial use.',tags:['coast','coastline','sea','golden','hour','drone','slow','wide','aerial','headland','no people'],source:'Atlantic_coast_033.mov',in:'00:01:02:00',out:'00:01:20:00',confidence:'0.89'},
{id:'04',title:'Waves beneath the cliffs',duration:6.5,resolution:'1080p',motion:'Static',size:'Medium',paid:true,position:'18% 80%',description:'Ocean foam and textured rock fill the frame in a shorter, static shot.',tags:['coast','coastline','ocean','sea','waves','rocks','golden','hour','static','medium','no people'],source:'Atlantic_coast_040.mov',in:'00:00:05:00',out:'00:00:11:12',confidence:'0.87'},
{id:'05',title:'The last light',duration:10.8,resolution:'4K',motion:'Slow drone',size:'Wide',paid:true,position:'10% 15%',description:'The sun catches the horizon in a slow, open coastal view.',tags:['coast','coastline','ocean','golden','hour','sunset','sun','drone','slow','wide','aerial','no people'],source:'Atlantic_coast_047.mov',in:'00:00:42:03',out:'00:00:52:23',confidence:'0.93'},
{id:'06',title:'Ocean textures',duration:4.1,resolution:'1080p',motion:'Static',size:'Close-up',paid:false,position:'50% 90%',description:'A brief detail of textured water. Editorial only in this sample dataset.',tags:['coast','coastline','ocean','sea','water','texture','close','static','golden','hour','no people'],source:'Atlantic_coast_052.mov',in:'00:00:01:00',out:'00:00:05:02',confidence:'0.85'}
];
const queryInput=document.querySelector('#shot-query');
const filter4k=document.querySelector('#filter-4k'),filterLong=document.querySelector('#filter-long'),filterRights=document.querySelector('#filter-rights');
const results=document.querySelector('#shot-results');
function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function renderShots(){if(!results)return;const q=queryInput.value.toLowerCase().trim();const need4k=filter4k.checked||/\b4k\b/.test(q),needLong=filterLong.checked||/\b(8|eight)\b/.test(q),needRights=filterRights.checked||/paid|cleared|commercial/.test(q);const stopWords=new Set(['4k','8','eight','second','seconds','at','least','for','the','of','a','shot','shots','footage','cleared','paid','social','commercial','and','in','with','no','people']);const tokens=q.split(/\W+/).filter(t=>t.length>2&&!stopWords.has(t));const matches=shots.filter(s=>(!need4k||s.resolution==='4K')&&(!needLong||s.duration>=8)&&(!needRights||s.paid)&&tokens.every(t=>s.tags.some(tag=>tag.includes(t))));document.querySelector('#result-count').textContent=`${matches.length} sample shot${matches.length===1?'':'s'}${needRights?' · paid social cleared':''}`;if(!matches.length){results.innerHTML='<div class="empty-results"><strong>No matching sample shots.</strong><p>This sample collection contains coastal footage. Try “coast”, “drone” or “waves”, or reset your filters.</p><button type="button" class="empty-reset">Show all sample shots</button></div>';return;}results.innerHTML=matches.map(s=>`<button type="button" class="shot-card" data-shot="${s.id}" aria-label="Inspect ${s.title}"><div class="shot-thumb"><img src="/assets/coast-800.webp" alt="${s.title}: illustrative coastal footage" width="800" height="533" loading="lazy" style="--shot-zoom:${({'01':1,'02':1.55,'03':1.25,'04':2.5,'05':1.8,'06':3})[s.id]};--shot-origin:${s.position};object-position:${s.position};${s.id==='04'?'filter:saturate(.7)':s.id==='06'?'filter:brightness(.85)':''}"><span class="shot-duration">${s.duration.toFixed(1)}s</span></div><span class="shot-title"><span>${s.title}</span><span>${s.resolution}</span></span><span class="shot-reason">${s.motion} · ${s.size} · Golden hour</span><span class="shot-rights${s.paid?'':' restricted'}">${s.paid?'✓ Paid social cleared':'Editorial use only'}</span></button>`).join('');}
const searchForm=document.querySelector('#search-form');searchForm?.addEventListener('submit',e=>{e.preventDefault();renderShots();});queryInput?.addEventListener('input',renderShots);
[filter4k,filterLong,filterRights].forEach(f=>f?.addEventListener('change',renderShots));
function resetDemo(){filter4k.checked=false;filterLong.checked=false;filterRights.checked=false;queryInput.value='';renderShots();}
document.querySelector('.reset-filters')?.addEventListener('click',resetDemo);
document.querySelectorAll('[data-query]').forEach(b=>b.addEventListener('click',()=>{filter4k.checked=false;filterLong.checked=false;filterRights.checked=false;queryInput.value=b.dataset.query;renderShots();}));
results?.addEventListener('click',e=>{if(e.target.closest('.empty-reset')){resetDemo();return;}const card=e.target.closest('[data-shot]');if(!card)return;const s=shots.find(s=>s.id===card.dataset.shot);document.querySelector('#shot-dialog-title').textContent=s.title;document.querySelector('#detail-description').textContent=s.description;document.querySelector('#detail-image').style.objectPosition=s.position;document.querySelector('#detail-signals').innerHTML=[['File',s.source],['In / out',`${s.in} / ${s.out}`],['Duration · measured',`${s.duration.toFixed(1)} seconds`],['Resolution · metadata',s.resolution],['Camera motion · measured',s.motion],['Coastline · model confidence',s.confidence],['Paid social · recorded rights',s.paid?'Cleared':'Not cleared']].map(([k,v])=>`<div><dt>${escapeHTML(k)}</dt><dd>${escapeHTML(v)}</dd></div>`).join('');document.querySelector('#shot-dialog').showModal();});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.querySelector('a[href="#get-started"]')?.addEventListener('click',()=>d.close());});
document.querySelector('[data-screenshot]')?.addEventListener('click',()=>document.querySelector('#screenshot-dialog').showModal());
const tabs=Array.from(document.querySelectorAll('.install-tabs [role="tab"]'));
function selectTab(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected;});}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[next]);tabs[next].focus();}});});
document.querySelectorAll('.copy-code').forEach(b=>b.addEventListener('click',async()=>{const text=document.querySelector(`#${b.dataset.copy} code`).textContent;try{await navigator.clipboard.writeText(text);b.textContent='Copied';document.querySelector('.copy-status').textContent='Commands copied. Replace the password and footage path before running.';setTimeout(()=>b.textContent='Copy commands',2200);}catch{document.querySelector('.copy-status').textContent='Copy is unavailable in this browser. Select the commands above and copy them manually.';}}));
renderShots();

const heroForm=document.querySelector('#hero-search-form');
heroForm?.addEventListener('submit',e=>{e.preventDefault();filter4k.checked=false;filterLong.checked=false;filterRights.checked=false;queryInput.value=document.querySelector('#hero-query').value;renderShots();document.querySelector('#demo').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});queryInput.focus({preventScroll:true});});
